create table if not exists public.fleet_maintenance_records (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, vehicle_id uuid not null references public.fleet_vehicles(id) on delete cascade, maintenance_type text not null, status text not null default 'scheduled', scheduled_at timestamptz, completed_at timestamptz, odometer_miles numeric, cost numeric, vendor text, notes text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists fleet_maintenance_business_idx on public.fleet_maintenance_records(business_id,status,scheduled_at);
create table if not exists public.fleet_driver_scorecards (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, driver_id uuid not null references public.fleet_drivers(id) on delete cascade, score_date date not null, safety_score numeric, efficiency_score numeric, route_completion_score numeric, idle_minutes numeric, harsh_braking_count integer, harsh_acceleration_count integer, speeding_events integer, collision_events integer, seatbelt_events integer, notes text, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(driver_id,score_date)); create index if not exists fleet_driver_scorecards_business_date_idx on public.fleet_driver_scorecards(business_id,score_date desc);
create table if not exists public.fleet_vehicle_daily_metrics (id uuid primary key default gen_random_uuid(), business_id uuid not null references public.businesses(id) on delete cascade, vehicle_id uuid not null references public.fleet_vehicles(id) on delete cascade, metric_date date not null, miles numeric default 0, engine_hours numeric default 0, trips integer default 0, fuel_units numeric, energy_kwh numeric, idle_minutes numeric default 0, utilization_pct numeric, fault_events integer default 0, maintenance_due boolean not null default false, metadata jsonb not null default '{}'::jsonb, created_at timestamptz not null default now(), unique(vehicle_id,metric_date)); create index if not exists fleet_vehicle_metrics_business_date_idx on public.fleet_vehicle_daily_metrics(business_id,metric_date desc);
create or replace view public.fleet_service_opportunities as select l.id location_id,l.name,l.latitude,l.longitude,l.business_id,l.bathroom_verification_status,l.rating,l.accessible,l.changing_table,coalesce(la.amenity_count,0) amenity_count,coalesce(lq.observation_count,0) quality_observation_count,case when l.bathroom_verification_status in ('verified','user_verified','business_verified') then 1 else 0 end verified_bathroom,case when coalesce(lq.observation_count,0)=0 then 1 else 0 end needs_fresh_observation from public.locations l left join (select location_id,count(*) amenity_count from public.location_amenities group by location_id) la on la.location_id=l.id left join (select location_id,count(*) observation_count from public.location_quality_observations group by location_id) lq on lq.location_id=l.id where coalesce(l.is_active,true)=true;
create or replace function public.fleet_dashboard_summary_v2(p_business_id uuid) returns jsonb language sql stable security definer set search_path=public as $$ with veh as (select count(*) total,count(*) filter(where status='active') active,coalesce(sum(odometer_miles),0) odometer from fleet_vehicles where business_id=p_business_id),drv as (select count(*) total,count(*) filter(where status='active') active from fleet_drivers where business_id=p_business_id),rte as (select count(*) total,count(*) filter(where status='active') active,count(*) filter(where status in ('completed','complete')) completed,coalesce(sum(distance_miles),0) miles,coalesce(sum(estimated_minutes),0) minutes from fleet_routes where business_id=p_business_id),alt as (select count(*) filter(where status='open') open,count(*) total from fleet_alerts where business_id=p_business_id),ops as (select count(*) events,count(*) filter(where lower(event_type) in ('hard_brake','hard_braking','harsh_braking','hard_acceleration','harsh_acceleration','speeding','collision','seatbelt')) safety_events,coalesce(sum(event_value) filter(where unit ilike '%mile%'),0) miles,coalesce(sum(event_value) filter(where unit ilike '%minute%'),0) minutes from fleet_operational_events where business_id=p_business_id),maint as (select count(*) filter(where status in ('scheduled','due','overdue')) due,coalesce(sum(cost) filter(where completed_at is not null),0) maintenance_spend from fleet_maintenance_records where business_id=p_business_id),loc as (select count(*) total,count(*) filter(where bathroom_verification_status in ('verified','user_verified','business_verified')) verified,count(*) filter(where accessible=true) accessible,count(*) filter(where changing_table=true) changing_tables from locations where is_active=true),opp as (select count(*) opportunities,count(*) filter(where needs_fresh_observation=1) stale_opportunities from fleet_service_opportunities) select jsonb_build_object('vehicles',veh.total,'vehicles_active',veh.active,'odometer_miles',veh.odometer,'drivers',drv.total,'drivers_active',drv.active,'routes',rte.total,'routes_active',rte.active,'routes_completed',rte.completed,'route_miles',rte.miles,'route_minutes',rte.minutes,'open_alerts',alt.open,'alerts_total',alt.total,'operational_events',ops.events,'safety_events',ops.safety_events,'telemetry_miles',ops.miles,'telemetry_minutes',ops.minutes,'maintenance_due',maint.due,'maintenance_spend',maint.maintenance_spend,'location_total',loc.total,'location_verified',loc.verified,'location_accessible',loc.accessible,'location_changing_tables',loc.changing_tables,'service_opportunities',opp.opportunities,'stale_service_opportunities',opp.stale_opportunities) from veh cross join drv cross join rte cross join alt cross join ops cross join maint cross join loc cross join opp; $$;
create or replace function public.apply_user_amenity_confirmation() returns trigger language plpgsql security definer set search_path=public as $$ declare amenity_name text; positive boolean; begin positive:=lower(coalesce(new.status,'')) in ('yes','present','verified','confirmed','true','available'); if not positive then return new; end if; select name into amenity_name from public.amenities where id=new.amenity_id; insert into public.location_amenities(location_id,amenity_id) values(new.location_id,new.amenity_id) on conflict do nothing; update public.locations set accessible=case when lower(coalesce(amenity_name,'')) in ('accessible','accessible stall') then true else accessible end,changing_table=case when lower(coalesce(amenity_name,'')) in ('changing table','baby changing') then true else changing_table end,updated_at=now() where id=new.location_id; insert into public.data_feature_events(subject_type,subject_id,actor_user_id,location_id,event_type,feature_code,source_table,source_id,value_numeric,value_text,metadata,occurred_at) values('location',new.location_id,new.user_id,new.location_id,'amenity_confirmed','amenity_verification','location_amenity_observations',new.id,coalesce(new.confidence,1),amenity_name,jsonb_build_object('verification_method',new.verification_method,'status',new.status,'amenity_id',new.amenity_id),coalesce(new.observed_at,now())); return new; end; $$;
drop trigger if exists trg_user_amenity_confirmation on public.location_amenity_observations; create trigger trg_user_amenity_confirmation after insert on public.location_amenity_observations for each row execute function public.apply_user_amenity_confirmation();
create or replace function public.apply_external_amenity_to_location(p_location_id uuid,p_attribute_key text,p_value_text text) returns void language plpgsql security definer set search_path=public as $$ declare aid uuid; v text:=lower(coalesce(p_value_text,'')); k text:=lower(coalesce(p_attribute_key,'')); begin if v not in ('yes','true','present','available','limited') then return; end if; select a.id into aid from public.amenities a where lower(a.name)=case k when 'changing_table' then 'changing table' when 'changing_table_present' then 'changing table' when 'wheelchair' then 'accessible' when 'toilets:wheelchair' then 'accessible stall' when 'handwashing:soap' then 'soap' when 'toilets:hands_drying' then 'hand dryer' when 'hot_water' then 'hot water' when 'toilets:paper_supplied' then 'paper towels' when 'drinking_water' then 'drinking water' when 'shower' then 'showers' else '' end limit 1; if aid is not null then insert into public.location_amenities(location_id,amenity_id) values(p_location_id,aid) on conflict do nothing; end if; end; $$;
create or replace function public.apply_external_amenity_observation() returns trigger language plpgsql security definer set search_path=public as $$ begin if new.verification_state='externally_sourced' and new.value_text is not null then perform public.apply_external_amenity_to_location(new.location_id,new.attribute_key,new.value_text); end if; return new; end; $$;
drop trigger if exists trg_external_amenity_observation on public.external_observations; create trigger trg_external_amenity_observation after insert or update of value_text,verification_state,attribute_key on public.external_observations for each row execute function public.apply_external_amenity_observation();
insert into public.external_data_sources(source_key,name,source_url,license_name,license_url,attribution_text,active) select 'openstreetmap','OpenStreetMap','https://www.openstreetmap.org','ODbL 1.0','https://opendatacommons.org/licenses/odbl/1-0/','© OpenStreetMap contributors',true where not exists(select 1 from public.external_data_sources where source_key='openstreetmap');
